using Flow4Tech.Comandas.Application;
using Flow4Tech.Pagamentos.Application;

namespace Flow4Tech.Api;

/// <summary>
/// One method line of a receipt. <c>PagamentoId</c> is generated by the client (UUID v7). <c>RecebidoCentavos</c> is the money handed over for the bill (change only for cash); <c>GorjetaCentavos</c> is an optional tip on
/// top (needs <c>pagamento:registrar-gorjeta</c>). <c>DivisaoId</c> and <c>DivisaoParte</c> (both or none) pay a part of a recorded split of the comanda.
/// </summary>
internal sealed record LinhaDeRecebimentoRequest(Guid PagamentoId, Guid MetodoId, long RecebidoCentavos, long? GorjetaCentavos, Guid? DivisaoId, int? DivisaoParte);

/// <summary>A partial, split or mixed payment: one to ten lines of one payer, in one step. <c>Versao</c> is the comanda version the screen saw. More than one line, or a line paying a part of a split, needs <c>pagamento:dividir</c>.</summary>
internal sealed record ReceberLinhasRequest(int Versao, List<LinhaDeRecebimentoRequest> Linhas);

/// <summary>The lines as stored (a repeat answers the same) and the bill after them (its <c>Versao</c> is the one the next write must carry).</summary>
internal sealed record RecebimentoDto(List<PagamentoDto> Pagamentos, ContaDto Conta);

internal static class ComandasRecebimentoEndpoints
{
    private const long Body = 8192;

    public static void MapRecebimentoMisto(this IEndpointRouteBuilder app)
    {
        ArgumentNullException.ThrowIfNull(app);

        app.MapPost("/comandas/{comandaId:guid}/recebimentos", async (Guid comandaId, ReceberLinhasRequest body, RequestContextAccessor request, GestaoDoRecebimento recebimento, CancellationToken cancellationToken) =>
            {
                var linhas = (body.Linhas ?? []).Select(l => new LinhaDoRecebimento(l.PagamentoId, l.MetodoId, l.RecebidoCentavos, l.GorjetaCentavos ?? 0, l.DivisaoId, l.DivisaoParte)).ToList();
                var r = await recebimento.ReceberLinhasAsync(request, comandaId, body.Versao, linhas, cancellationToken);
                if (r.Resultado is not (ResultadoDoRecebimento.Ok or ResultadoDoRecebimento.Repetida))
                {
                    return ComandasEndpoints.ErroDeRecebimento(r);
                }

                var repetida = r.Resultado == ResultadoDoRecebimento.Repetida;
                var conta = repetida ? await recebimento.ContaAsync(request, comandaId, cancellationToken) : r;
                var dto = new RecebimentoDto(r.Pagamentos!.Select(ComandasEndpoints.PagamentoParaDto).ToList(), ComandasEndpoints.ContaParaDto(conta));
                return Results.Json(dto, statusCode: repetida ? StatusCodes.Status200OK : StatusCodes.Status201Created);
            })
            .WithName("receberRecebimentoDaComanda")
            .RequireSession()
            .WithBodyLimit(Body)
            .RequirePermission(ComandaPermissions.ReceberPagamento)
            .Produces<RecebimentoDto>(StatusCodes.Status201Created)
            .Produces<RecebimentoDto>()
            .Produces<ComandaErro>(StatusCodes.Status400BadRequest)
            .Produces(StatusCodes.Status401Unauthorized)
            .Produces(StatusCodes.Status403Forbidden)
            .Produces<ComandaErro>(StatusCodes.Status404NotFound)
            .Produces<ComandaErro>(StatusCodes.Status409Conflict);
    }
}
